"use client";

import { PanelLeft, PanelLeftClose } from "lucide-react";
import {
  useCallback,
  useEffect,
  useId,
  useImperativeHandle,
  useMemo,
  useRef,
} from "react";
import { cn } from "@/lib/utils";
import { Sheet, SheetContent, SheetTitle } from "@/components/ui/sheet";
import { useActiveDetection } from "./hooks/use-active-detection";
import { useMatchMedia, resolveBreakpointQuery } from "./hooks/use-match-media";
import { useSidebarReducer } from "./hooks/use-sidebar-reducer";
import { useStorageSync } from "./hooks/use-storage-sync";
import {
  AppSidebarContext,
  type AppSidebarContextValue,
} from "./contexts/sidebar-nav-context";
import { buildHandle } from "./lib/build-handle";
import { deriveCssVars } from "./lib/derive-css-vars";
import { flattenEntriesForKeyboard } from "./lib/flatten-entries";
import { handleSidebarKeydown } from "./lib/keyboard-handler";
import { DefaultLink } from "./parts/default-link";
import { NavBrand } from "./parts/nav-brand";
import { NavPrimaryAction } from "./parts/nav-primary-action";
import { NavUser } from "./parts/nav-user";
import { SidebarEmptyState } from "./parts/sidebar-empty-state";
import { SidebarLoadingSkeleton } from "./parts/sidebar-loading-skeleton";
import { SidebarNavList } from "./parts/sidebar-nav-list";
import { SidebarSkipLink } from "./parts/sidebar-skip-link";
import type {
  NavItem,
  NavUserMenuItemSelectEvent,
  AppSidebarEmptyReason,
  AppSidebarHandle,
  AppSidebarMobileOpenReason,
  AppSidebarProps,
} from "./types";

/** Breakpoint → CSS class lookup (L44 — CSS-gated, not JS-gated rendering). */
const BREAKPOINT_DESKTOP_VISIBLE: Record<string, string> = {
  sm: "sm:flex",
  md: "md:flex",
  lg: "lg:flex",
  xl: "xl:flex",
  "2xl": "2xl:flex",
};
const BREAKPOINT_MOBILE_VISIBLE: Record<string, string> = {
  sm: "sm:hidden",
  md: "md:hidden",
  lg: "lg:hidden",
  xl: "xl:hidden",
  "2xl": "2xl:hidden",
};

/**
 * C3 — items rendering + active detection.
 *
 * Items now actually render. Active item highlighted (full-fill paint;
 * activeVariant matrix lands C5). Sections render their items inline
 * (full section UI with header lands C4). Click sequence per L28 wired.
 */
export function AppSidebar(props: AppSidebarProps) {
  const {
    items,
    currentPath,
    isActive,
    defaultMatch = "exact",
    linkComponent = DefaultLink,
    className,
    id: idProp,
    "aria-label": ariaLabel = "Main navigation",
    defaultCollapsed,
    defaultMobileOpen,
    defaultCollapsedSectionIds,
    isCollapsed,
    isMobileOpen,
    onCollapsedChange,
    onMobileOpenChange,
    onItemClick,
    onItemHover,
    onItemFocus,
    onItemNavigate,
    onActiveItemChange,
    onMount,
    onUnmount,
    onSectionToggle,
    autoCloseMobileOnNavigate = true,
    keepEmptySections = false,
    permissions,
    renderItem,
    renderSection,
    renderBadge,
    renderTooltipContent,
    renderLoading,
    renderEmptyState,
    loading = false,
    state: externalState,
    storageKey,
    autoExpandActiveSection = true,
    autoScrollActiveIntoView = true,
    brandSlot,
    brand,
    headerSlot,
    navAccessorySlot,
    primaryActionSlot,
    primaryAction,
    footerSlot,
    footer,
    side = "left",
    activeVariant = "fill",
    collapsedWidth,
    expandedWidth,
    transitionDuration,
    style,
    mobileBreakpoint = "lg",
    mobileDrawerSide,
    drawerHeaderSlot,
    skipLinkTarget,
    skipLinkLabel = "Skip to content",
    onPermissionDenied,
    onSkipLinkActivated,
    onBrandClick,
    onPrimaryActionClick,
    onFooterTriggerOpen,
    onFooterMenuItemClick,
    ref: externalRef,
    // v0.2.0 — additive (L41–L52)
    topSlot,
    hrefTemplateValues,
    resolveHref,
    isOwner,
    currentMaxMembers,
    bypassFiltering,
  } = props;

  // L32: id defaults via useId() for <SidebarNavTrigger aria-controls>
  const autoId = useId();
  const sidebarId = idProp ?? `app-sidebar-${autoId}`;

  // Section-collapse init priority (plan §8): explicit prop > per-section
  // defaultCollapsed. Storage rehydration (C11) will outrank both via
  // EXTERNAL_SYNC after mount.
  const initialCollapsedSectionIds = useMemo(() => {
    if (defaultCollapsedSectionIds) return defaultCollapsedSectionIds;
    const fromItems: string[] = [];
    for (const entry of items) {
      if (entry.kind === "section" && entry.defaultCollapsed) {
        fromItems.push(entry.id);
      }
    }
    return fromItems;
  }, [defaultCollapsedSectionIds, items]);

  // Reducer + Defense-1 + Defense-2 wiring
  const { state, dispatch } = useSidebarReducer({
    defaultCollapsed,
    defaultMobileOpen,
    defaultCollapsedSectionIds: initialCollapsedSectionIds,
    isCollapsed,
    isMobileOpen,
    onCollapsedChange,
    onMobileOpenChange,
  });

  // localStorage opt-in (L23). Per L43: when external `state` provided,
  // the hook owns storageKey; component's storageKey is ignored + dev warn.
  const effectiveStorageKey = externalState ? undefined : storageKey;
  if (
    externalState &&
    storageKey &&
    process.env.NODE_ENV !== "production"
  ) {
    console.warn(
      "[app-sidebar] `storageKey` is ignored when `state` (lifted hook) is provided — the hook owns persistence (L43). Move storageKey to useAppSidebarState() options.",
    );
  }
  useStorageSync(state, dispatch, effectiveStorageKey);

  // Items pipeline: derive visible entries → compute active item
  const { visible, active } = useActiveDetection({
    items,
    currentPath,
    isActive,
    defaultMatch,
    permissions,
    keepEmptySections,
    // v0.2.0 — three-gate intersection (L46) + bypass (Q21)
    isOwner,
    currentMaxMembers,
    bypassFiltering,
  });

  // F1 — auto-expand section containing the active item (L48-b).
  // When external state is provided, the hook (useAppSidebarState)
  // owns F1; component-internal effect skipped to avoid double-firing.
  useEffect(() => {
    if (externalState) return;
    if (!autoExpandActiveSection) return;
    if (!active.sectionId) return;
    if (!state.collapsedSectionIds.has(active.sectionId)) return;
    dispatch({
      type: "SET_SECTION_COLLAPSED",
      sectionId: active.sectionId,
      collapsed: false,
    });
  }, [
    externalState,
    autoExpandActiveSection,
    active.sectionId,
    state.collapsedSectionIds,
    dispatch,
  ]);

  // Breakpoint resolution — CSS class names for the L44 CSS-gated render path.
  // `useMatchMedia` returns the live mobile state for JS BEHAVIOR gating only
  // (e.g., autoCloseMobileOnNavigate timing decisions — actual visual swap is
  // CSS-driven, no SSR flash).
  const desktopVisibleClass =
    typeof mobileBreakpoint === "string" &&
    mobileBreakpoint in BREAKPOINT_DESKTOP_VISIBLE
      ? BREAKPOINT_DESKTOP_VISIBLE[mobileBreakpoint]
      : "lg:flex";
  const mobileVisibleClass =
    typeof mobileBreakpoint === "string" &&
    mobileBreakpoint in BREAKPOINT_MOBILE_VISIBLE
      ? BREAKPOINT_MOBILE_VISIBLE[mobileBreakpoint]
      : "lg:hidden";

  const isMobileBehavior = useMatchMedia(resolveBreakpointQuery(mobileBreakpoint));

  // closeMobile / toggleSection are wired through `finalHandle` so they
  // mutate the EXTERNAL state when one is provided, or the internal
  // reducer otherwise. Trade-off (L20 reasons): when external state,
  // the auto-close path loses the "item-click" reason discriminator —
  // `onMobileOpenChange` fires with "imperative" instead. Acceptable
  // for v0.1; a future polish commit can add `setMobileOpenWithReason`
  // to the handle if needed.

  // Imperative handle — refreshed with items + active-detection results.
  // v0.3.0 (C5, F5): delegated to the shared `buildHandle` factory.
  // Identical factory consumed by `useAppSidebarState` so the two state
  // paths can't drift apart.
  const handle = useMemo<AppSidebarHandle>(
    () => buildHandle({ state, dispatch, items, visible, active }),
    [state, dispatch, items, visible, active],
  );

  // L30 — state prop precedence: external lifted state wins entirely over
  // internal reducer state. Internal reducer still computed for hooks-rules
  // compliance (L47), but its values flow through `finalCollapsed` /
  // `finalMobileOpen` / etc. only when external state isn't supplied.
  const finalCollapsed = externalState?.collapsed ?? state.collapsed;
  const finalMobileOpen = externalState?.mobileOpen ?? state.mobileOpen;
  const finalCollapsedSectionIds =
    externalState?.collapsedSectionIds ?? state.collapsedSectionIds;
  const finalActiveItem = externalState?.activeItem ?? active.item;
  const finalVisibleEntries = externalState?.visibleEntries ?? visible.entries;
  const finalHandle: AppSidebarHandle = externalState ?? handle;

  // F-cross-13 (v0.3.2): `onPointerDownOutside` / `onEscapeKeyDown` are
  // Radix-only SheetContent props — Base UI's DialogPopup rejects them. The
  // public `onMobileOpenChange.reason` discriminator ("outside-click" |
  // "escape") survives via own attribution: capture-phase document listeners
  // record the reason (with a freshness stamp so a non-closing Escape can't
  // mis-tag a later close); the cross-backend onOpenChange dispatch reads it.
  const mobilePanelRef = useRef<HTMLDivElement | null>(null);
  const mobileCloseReasonRef = useRef<{
    reason: AppSidebarMobileOpenReason;
    t: number;
  } | null>(null);
  useEffect(() => {
    if (!finalMobileOpen) return;
    const onPointerDown = (e: PointerEvent) => {
      const panel = mobilePanelRef.current;
      if (panel && e.target instanceof Node && !panel.contains(e.target)) {
        mobileCloseReasonRef.current = { reason: "outside-click", t: Date.now() };
      }
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        mobileCloseReasonRef.current = { reason: "escape", t: Date.now() };
      }
    };
    document.addEventListener("pointerdown", onPointerDown, true);
    document.addEventListener("keydown", onKeyDown, true);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown, true);
      document.removeEventListener("keydown", onKeyDown, true);
      mobileCloseReasonRef.current = null;
    };
  }, [finalMobileOpen]);

  // Flattened keyboard traversal sequence (L37). Section headers (collapsible
  // only) interleave with their items; items hide when section is collapsed.
  const keyboardFlat = useMemo(
    () =>
      flattenEntriesForKeyboard(finalVisibleEntries, finalCollapsedSectionIds),
    [finalVisibleEntries, finalCollapsedSectionIds],
  );
  const keyboardEntryId = keyboardFlat.length > 0 ? keyboardFlat[0].id : null;

  // Reducer-driven focus state. Even when external `state` is provided,
  // focus tracking lives in the internal reducer — focus is transient UI,
  // not persistable consumer state.
  const focusedItemId = state.focusedItemId;

  // L38 — onPermissionDenied diff-firing. Fire once per item initially +
  // again for any item NEWLY entering the filtered set on subsequent renders.
  // Comparison runs on each render via the ref-tracked previous set.
  const prevFilteredRef = useRef<ReadonlySet<string> | null>(null);
  useEffect(() => {
    const currentFiltered = visible.filteredByPermission;
    const currentIds = new Set(currentFiltered.map((f) => f.item.id));
    if (onPermissionDenied) {
      const prevIds = prevFilteredRef.current;
      for (const entry of currentFiltered) {
        if (prevIds === null || !prevIds.has(entry.item.id)) {
          onPermissionDenied({
            item: entry.item,
            requiredPermission: entry.requiredPermission,
          });
        }
      }
    }
    prevFilteredRef.current = currentIds;
  }, [visible.filteredByPermission, onPermissionDenied]);

  // Programmatic focus follow-up — when reducer's focusedItemId changes,
  // move DOM focus to the matching row (via `data-nav-id`). Layout effect
  // so focus lands before the browser paints, avoiding visible flashes.
  useEffect(() => {
    if (!focusedItemId) return;
    if (typeof document === "undefined") return;
    const nav = document.getElementById(sidebarId);
    if (!nav) return;
    // v0.3.0 (C3, F3): CSS.escape is universal in modern browsers
    // (Chrome 46+ / Edge 79+ / Firefox 31+ / Safari 10+) — the SSR guard
    // above already gates this code to the browser. The old `replace`
    // fallback only escaped `"` and `\`, missing `:`, `]`, leading digits,
    // and dozens of other selector-illegal characters.
    const escaped = window.CSS.escape(focusedItemId);
    const target = nav.querySelector<HTMLElement>(
      `[data-nav-id="${escaped}"]`,
    );
    if (target && document.activeElement !== target) {
      target.focus();
    }
  }, [focusedItemId, sidebarId]);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLElement>) => {
      handleSidebarKeydown(event, {
        flat: keyboardFlat,
        focusedId: focusedItemId,
        setFocusedId: (id) => dispatch({ type: "FOCUS_ITEM", itemId: id }),
        toggleSection: (id) => finalHandle.toggleSection(id),
        isSectionCollapsed: (id) => finalCollapsedSectionIds.has(id),
      });
    },
    [keyboardFlat, focusedItemId, dispatch, finalHandle, finalCollapsedSectionIds],
  );

  // F2 — auto-scroll active item into view on mount + currentPath change (L48-c)
  useEffect(() => {
    if (!autoScrollActiveIntoView) return;
    if (typeof document === "undefined") return;
    if (!finalActiveItem) return;
    const nav = document.getElementById(sidebarId);
    if (!nav) return;
    const activeEl = nav.querySelector('[data-active="true"]');
    if (!(activeEl instanceof HTMLElement)) return;
    const reducedMotion =
      typeof window !== "undefined" &&
      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    activeEl.scrollIntoView({
      block: "nearest",
      behavior: reducedMotion ? "auto" : "smooth",
    });
  }, [autoScrollActiveIntoView, finalActiveItem, sidebarId]);

  // Helpers used by render — wired through finalHandle so they mutate
  // external state (when provided) or internal reducer (default).
  // v0.3.0 (C2, L54): closeMobile accepts a reason for the discriminator
  // (default "imperative" if unspecified — preserves v0.2.x callers).
  const closeMobile = useCallback(
    (reason?: AppSidebarMobileOpenReason) => {
      if (!isMobileBehavior) return;
      finalHandle.closeMobile(reason);
    },
    [finalHandle, isMobileBehavior],
  );

  const toggleSection = useCallback(
    (sectionId: string) => {
      finalHandle.toggleSection(sectionId);
    },
    [finalHandle],
  );

  // Attach the imperative handle to the consumer-supplied ref (React 19
  // ref-as-prop pattern). When external state provided, ref exposes the
  // external handle so trigger toggles drive the right state machine.
  useImperativeHandle(externalRef, () => finalHandle, [finalHandle]);

  /*
   * v0.3.1 — lifecycle + derived-state events.
   *
   * `onItemHover`, `onItemFocus`, `onActiveItemChange`, `onMount` and
   * `onUnmount` were all declared in `AppSidebarProps`, documented in the
   * description, and never read by a single line of implementation. The plan
   * doc even carries a High review finding correcting `onActiveItemChange`'s
   * TIMING (P2) — a careful argument about a callback that was then wired to
   * nothing. `NavLinkProps` had likewise declared `onMouseEnter`/`onFocus`
   * from the start with nothing passing them.
   */
  const firedMountRef = useRef(false);
  useEffect(() => {
    if (firedMountRef.current) return;
    firedMountRef.current = true;
    onMount?.({ initialState: finalHandle.getState() });
    // Mount-only by contract: `initialState` is the state AT mount. Re-running
    // on handle identity would re-announce a mount that already happened.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Unmount fires during cleanup, when props are already gone — so the latest
  // callback is held in a ref rather than captured in the effect closure.
  const onUnmountRef = useRef(onUnmount);
  useEffect(() => {
    onUnmountRef.current = onUnmount;
  }, [onUnmount]);
  useEffect(
    () => () => {
      onUnmountRef.current?.();
    },
    [],
  );

  /*
   * `activeItem` is DERIVED from `currentPath`, which changes when the host's
   * router commits — so this is reactive, not click-synchronous. Firing it from
   * the click handler (the original design) would report a change that had not
   * happened yet, and miss every navigation the host performed on its own.
   *
   * The initial value is not a "change": it is delivered by `onMount`'s
   * `initialState`. Comparing by `id` keeps a re-rendered-but-equal item from
   * emitting a phantom transition.
   */
  const previousActiveItemRef = useRef<NavItem | null>(null);
  const activeChangeInitialisedRef = useRef(false);
  useEffect(() => {
    const item = finalActiveItem ?? null;
    if (!activeChangeInitialisedRef.current) {
      activeChangeInitialisedRef.current = true;
      previousActiveItemRef.current = item;
      return;
    }
    const previousItem = previousActiveItemRef.current;
    if ((previousItem?.id ?? null) === (item?.id ?? null)) return;
    previousActiveItemRef.current = item;
    onActiveItemChange?.({ item, previousItem });
  }, [finalActiveItem, onActiveItemChange]);

  const contextValue = useMemo<AppSidebarContextValue>(
    () => ({
      state: { ...state, collapsed: finalCollapsed, mobileOpen: finalMobileOpen, collapsedSectionIds: finalCollapsedSectionIds },
      dispatch,
      handle: finalHandle,
      sidebarId,
    }),
    [state, dispatch, finalHandle, sidebarId, finalCollapsed, finalMobileOpen, finalCollapsedSectionIds],
  );

  const cssVars = useMemo(
    () => deriveCssVars({ collapsedWidth, expandedWidth, transitionDuration }),
    [collapsedWidth, expandedWidth, transitionDuration],
  );

  const defaultAccessory = (
    <button
      type="button"
      onClick={() => finalHandle.toggleCollapse()}
      aria-label={finalCollapsed ? "Expand sidebar" : "Collapse sidebar"}
      aria-expanded={!finalCollapsed}
      aria-controls={sidebarId}
      className={cn(
        "inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-md",
        "text-muted-foreground hover:bg-muted hover:text-foreground",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card",
      )}
    >
      {finalCollapsed ? (
        <PanelLeft className="h-4 w-4" aria-hidden="true" />
      ) : (
        <PanelLeftClose className="h-4 w-4" aria-hidden="true" />
      )}
    </button>
  );

  // Shared inner chrome — used by BOTH desktop <nav> and mobile <Sheet>.
  // Single source of truth for the header / list / footer composition.
  //
  // Header-row visibility rules:
  //   desktop: ALWAYS renders (defaultAccessory always available unless
  //            consumer explicitly passes navAccessorySlot={null} to hide it
  //            AND supplies neither header nor brand → only then suppressed)
  //   mobile: renders only when drawerHeaderSlot OR headerSlot OR resolvedBrand
  //           supplied (mobile drawer has no collapse toggle — sheet close
  //           button handles that)
  // Slot-vs-config resolution (L13): slot wins over shorthand config.
  // Component-level events (onBrandClick / onPrimaryActionClick /
  // onFooterTriggerOpen / onFooterMenuItemClick) are wired into the resolved
  // prefabs here so they fire regardless of whether the consumer used the
  // shorthand config or supplied their own slot. Slot consumers wire their
  // own callbacks directly — the component-level callbacks only apply to
  // the prefab path.
  const resolvedBrand = useMemo(() => {
    if (brandSlot) return brandSlot;
    if (!brand) return null;
    const brandElement = <NavBrand {...brand} />;
    if (!onBrandClick) return brandElement;
    return (
      <span
        onClick={(event) => onBrandClick({ event })}
        className="contents"
      >
        {brandElement}
      </span>
    );
  }, [brandSlot, brand, onBrandClick]);

  const resolvedPrimaryAction = useMemo(() => {
    if (primaryActionSlot) return primaryActionSlot;
    if (!primaryAction) return null;
    if (!onPrimaryActionClick) return <NavPrimaryAction {...primaryAction} />;
    return (
      <NavPrimaryAction
        {...primaryAction}
        onClick={(event) => {
          primaryAction.onClick?.(event);
          onPrimaryActionClick({ event });
        }}
      />
    );
  }, [primaryActionSlot, primaryAction, onPrimaryActionClick]);

  const resolvedFooter = useMemo(() => {
    if (footerSlot) return footerSlot;
    if (!footer) return null;
    const wireMenuItem = onFooterMenuItemClick
      ? (() => {
          const wired = footer.menuItems.map((entry) => {
            if (entry.kind === "separator") return entry;
            const item = entry;
            return {
              ...item,
              // v0.3.0 (C4, F10): widened event arg matches NavUserMenuItem.onClick.
              onClick: (event: NavUserMenuItemSelectEvent) => {
                item.onClick?.(event);
                onFooterMenuItemClick({ menuItem: item, event });
              },
            };
          });
          return wired;
        })()
      : footer.menuItems;
    return (
      <NavUser
        {...footer}
        menuItems={wireMenuItem}
        onTriggerOpen={(args) => {
          footer.onTriggerOpen?.(args);
          onFooterTriggerOpen?.(args);
        }}
      />
    );
  }, [footerSlot, footer, onFooterTriggerOpen, onFooterMenuItemClick]);

  const desktopAccessory =
    navAccessorySlot === null ? null : (navAccessorySlot ?? defaultAccessory);
  const showMobileHeader = !!drawerHeaderSlot || !!headerSlot || !!resolvedBrand;

  // L39 — loading/empty branching precedence:
  //   loading=true → renderLoading slot OR default skeleton
  //   else items.length === 0 → renderEmptyState({reason: "no-items"})
  //   else visibleEntries.length === 0 AND filtered count > 0
  //     → renderEmptyState({reason: "all-filtered-by-permission"})
  //   else visibleEntries.length === 0 AND hidden count > 0
  //     → renderEmptyState({reason: "all-hidden"})
  //   else → normal list render
  //
  // v0.3.0 (C6, F7): wrapped in useCallback so consumers in non-React-Compiler
  // environments (registry installs into apps without the compiler) still get
  // stable references and avoid the cascade of <SidebarNavList> re-renders on
  // unrelated parent state changes.
  const renderListBody = useCallback(
    (mode: "desktop" | "mobile") => {
      const collapsed = mode === "mobile" ? false : finalCollapsed;

      if (loading) {
        const defaultRender = (
          <SidebarLoadingSkeleton isCollapsed={collapsed} />
        );
        if (renderLoading) {
          return renderLoading({ isCollapsed: collapsed, defaultRender });
        }
        return defaultRender;
      }

      if (finalVisibleEntries.length === 0) {
        // When external state is provided, internal `visible.*` diagnostic
        // counts are best-effort (may not match externalState.items). Reason
        // resolution is lossy in that path — defaults to "no-items".
        const reason: AppSidebarEmptyReason =
          items.length === 0
            ? "no-items"
            : visible.filteredByPermission.length > 0
              ? "all-filtered-by-permission"
              : visible.hiddenItemCount > 0
                ? "all-hidden"
                : "no-items";
        if (renderEmptyState) {
          return renderEmptyState({ reason });
        }
        return <SidebarEmptyState reason={reason} />;
      }

      return (
        <SidebarNavList
          entries={finalVisibleEntries}
          activeItemId={finalActiveItem?.id ?? null}
          focusedItemId={focusedItemId}
          keyboardEntryId={keyboardEntryId}
          isCollapsed={collapsed}
          linkComponent={linkComponent}
          activeVariant={activeVariant}
          autoCloseMobileOnNavigate={autoCloseMobileOnNavigate}
          isMobileOpen={finalMobileOpen}
          onCloseMobile={closeMobile}
          collapsedSectionIds={finalCollapsedSectionIds}
          onToggleSection={toggleSection}
          onItemClick={onItemClick}
          onItemHover={onItemHover}
          onItemFocus={onItemFocus}
          onItemNavigate={onItemNavigate}
          onSectionToggle={onSectionToggle}
          renderItem={renderItem}
          renderSection={renderSection}
          renderBadge={renderBadge}
          renderTooltipContent={renderTooltipContent}
          hrefTemplateValues={hrefTemplateValues}
          resolveHref={resolveHref}
        />
      );
    },
    [
      finalCollapsed,
      loading,
      renderLoading,
      finalVisibleEntries,
      items.length,
      visible.filteredByPermission.length,
      visible.hiddenItemCount,
      renderEmptyState,
      finalActiveItem?.id,
      focusedItemId,
      keyboardEntryId,
      linkComponent,
      activeVariant,
      autoCloseMobileOnNavigate,
      finalMobileOpen,
      closeMobile,
      finalCollapsedSectionIds,
      toggleSection,
      onItemClick,
      onItemHover,
      onItemFocus,
      onItemNavigate,
      onSectionToggle,
      renderItem,
      renderSection,
      renderBadge,
      renderTooltipContent,
      hrefTemplateValues,
      resolveHref,
    ],
  );

  // v0.3.0 (C6, F7): wrapped in useCallback — see note on renderListBody.
  const renderInnerChrome = useCallback(
    (mode: "desktop" | "mobile") => {
    const headerCollapsedDesktop = mode === "desktop" && finalCollapsed;
    // v0.2 — when topSlot is supplied with NO brand/headerSlot, the brand
    // row would otherwise render empty just to host the collapse toggle
    // (desktopAccessory), leaving a wasteful gap below topSlot. Merge the
    // accessory into the topSlot row instead (expanded desktop only —
    // collapsed mode keeps its own vertical-stack layout for the toggle).
    const mergeAccessoryIntoTopSlot =
      mode === "desktop" &&
      !headerCollapsedDesktop &&
      !!topSlot &&
      !headerSlot &&
      !resolvedBrand &&
      desktopAccessory !== null;
    const shouldShowBrandRow =
      mode === "desktop"
        ? !!headerSlot ||
          !!resolvedBrand ||
          (desktopAccessory !== null && !mergeAccessoryIntoTopSlot)
        : showMobileHeader;
    return (
    <>
      {/* v0.2.0 — topSlot above the brand zone (L41). Geographically distinct
       *  from headerSlot (which renders INSIDE the brand row). Zero layout
       *  shift when null/undefined per success #10. PQ3: unlabeled wrapper —
       *  ARIA semantics are the consumer's responsibility.
       *
       *  When `mergeAccessoryIntoTopSlot` is true (topSlot present, no brand
       *  row content of its own), the collapse toggle moves into this row
       *  pinned to the right — eliminates the empty brand-row gap. */}
      {topSlot ? (
        <div
          className={cn(
            "ilinxa-sidebar-top-slot border-b border-border",
            // Collapsed desktop: 80px-wide sidebar — center the topSlot
            // content so icon-only widgets (the canonical AccountSwitcher
            // 40×40 trigger) line up with the nav-row icons below. Without
            // this the icon sits left-aligned in p-3 padding (12+40+24 in
            // an 80px column) and visually drifts from the rest.
            headerCollapsedDesktop
              ? "flex items-center justify-center px-2 py-2"
              : "p-3",
            mergeAccessoryIntoTopSlot && "flex items-center gap-2",
          )}
        >
          {mergeAccessoryIntoTopSlot ? (
            <>
              <div className="min-w-0 flex-1">{topSlot}</div>
              <div className="shrink-0">{desktopAccessory}</div>
            </>
          ) : (
            topSlot
          )}
        </div>
      ) : null}

      {/* Brand / header zone.
       *
       * Layout:
       *   - expanded desktop / mobile drawer: horizontal flex — brand on the
       *     left, toggle on the right (`ml-auto`).
       *   - collapsed desktop: stack vertically and center — there isn't
       *     room for both brand (32px) and toggle (32px) plus gap inside
       *     an 80px-wide column without the two visually overlapping. */}
      {shouldShowBrandRow && (
        <div
          className={cn(
            "flex border-b border-border min-h-14",
            headerCollapsedDesktop
              ? "flex-col items-center gap-1 px-2 py-2"
              : "items-center gap-2 p-3",
          )}
        >
          {mode === "mobile" && drawerHeaderSlot ? (
            <div className="contents">{drawerHeaderSlot}</div>
          ) : (
            <>
              {headerSlot && <div className="contents">{headerSlot}</div>}
              {resolvedBrand && (
                <div
                  className={cn(
                    headerCollapsedDesktop
                      ? "flex shrink-0 items-center justify-center"
                      : "flex-1 min-w-0",
                  )}
                >
                  {resolvedBrand}
                </div>
              )}
              {!resolvedBrand && !headerSlot && !headerCollapsedDesktop && (
                <div className="flex-1" aria-hidden />
              )}
              {mode === "desktop" &&
                desktopAccessory !== null &&
                !mergeAccessoryIntoTopSlot && (
                  <div
                    className={cn(
                      headerCollapsedDesktop ? "shrink-0" : "ml-auto shrink-0",
                    )}
                  >
                    {desktopAccessory}
                  </div>
                )}
            </>
          )}
        </div>
      )}

      {/* Nav list — loading/empty branching per L39 */}
      <div className="flex flex-1 flex-col gap-2 overflow-hidden p-3">
        {renderListBody(mode)}
        {resolvedPrimaryAction && (
          <div className="pt-2">{resolvedPrimaryAction}</div>
        )}
      </div>

      {/* Footer zone */}
      {resolvedFooter && (
        <div className="border-t border-border p-3">{resolvedFooter}</div>
      )}
    </>
    );
    },
    [
      finalCollapsed,
      topSlot,
      headerSlot,
      resolvedBrand,
      desktopAccessory,
      showMobileHeader,
      drawerHeaderSlot,
      renderListBody,
      resolvedPrimaryAction,
      resolvedFooter,
    ],
  );

  const drawerSide = mobileDrawerSide ?? side;

  return (
    <AppSidebarContext.Provider value={contextValue}>
      {/* Desktop render path — CSS-hidden BELOW breakpoint (L44) */}
      <nav
        id={sidebarId}
        aria-label={ariaLabel}
        data-component="app-sidebar"
        data-collapsed={finalCollapsed}
        data-mobile-open={finalMobileOpen}
        data-side={side}
        onKeyDown={handleKeyDown}
        style={{ ...cssVars, ...style }}
        className={cn(
          "relative hidden h-full flex-col bg-card",
          desktopVisibleClass,
          // Side-aware border
          side === "left" ? "border-r" : "border-l",
          "border-border",
          // CSS-var-driven width + motion-safe transition
          "data-[collapsed=false]:w-(--ilinxa-sidebar-w-expanded)",
          "data-[collapsed=true]:w-(--ilinxa-sidebar-w-collapsed)",
          "motion-safe:transition-[width] motion-safe:duration-(--ilinxa-sidebar-transition-duration)",
          // RTL hook
          "rtl:border-x-0",
          side === "left" ? "rtl:border-l" : "rtl:border-r",
          className,
        )}
      >
        {skipLinkTarget && (
          <SidebarSkipLink
            target={skipLinkTarget}
            label={skipLinkLabel}
            onActivated={onSkipLinkActivated}
          />
        )}
        {renderInnerChrome("desktop")}
      </nav>

      {/* Mobile render path — CSS-hidden ABOVE breakpoint */}
      <div
        className={mobileVisibleClass}
        data-component="app-sidebar-mobile-wrapper"
        style={cssVars}
      >
        <Sheet
          open={finalMobileOpen}
          // F-cross-13 defensive: Radix passes (open: boolean); Base UI may pass
          // undefined or different shape. Runtime-check before mutating.
          // Routed through finalHandle so external state (when provided)
          // is the mutation target.
          //
          // v0.3.2 (F-cross-13): close reasons come from the document-level
          // attribution refs above (the Radix-only SheetContent props are
          // gone). A stamp older than 500ms is stale — e.g. an Escape that
          // didn't close — and falls back to the default reason.
          onOpenChange={(nextOpen: boolean | undefined) => {
            if (typeof nextOpen !== "boolean") return;
            if (nextOpen) {
              finalHandle.openMobile();
              return;
            }
            const stamped = mobileCloseReasonRef.current;
            mobileCloseReasonRef.current = null;
            if (stamped && Date.now() - stamped.t < 500) {
              finalHandle.closeMobile(stamped.reason);
            } else {
              finalHandle.closeMobile();
            }
          }}
        >
          <SheetContent
            ref={mobilePanelRef}
            side={drawerSide}
            // NOTE: do NOT add `relative` here — it would tailwind-merge
            // away Radix's `fixed inset-y-0 {side}-0`, leaving the panel
            // unpositioned and invisible against the overlay backdrop.
            className="flex w-72 flex-col bg-card p-0"
            style={cssVars}
            aria-describedby={undefined}
            onKeyDown={handleKeyDown}
          >
            <SheetTitle className="sr-only">{ariaLabel}</SheetTitle>
            {skipLinkTarget && (
              <SidebarSkipLink
                target={skipLinkTarget}
                label={skipLinkLabel}
                onActivated={onSkipLinkActivated}
              />
            )}
            {renderInnerChrome("mobile")}
          </SheetContent>
        </Sheet>
      </div>
    </AppSidebarContext.Provider>
  );
}

