  AppSidebarMobileOpenReason,
  AppSidebarProps,
} from "../types";
import { SidebarNavRow } from "./sidebar-nav-row";
import { SidebarNavSection } from "./sidebar-nav-section";
import { SidebarNavSeparator } from "./sidebar-nav-separator";

interface SidebarNavListProps {
  entries: ReadonlyArray<NavEntry>;
  activeItemId: string | null;
  focusedItemId: string | null;
  /**
   * Stable id of the first focusable item/section header in the rendered
   * traversal — used as the roving tabindex anchor when nothing is focused.
   * Null if no row is focusable (loading / empty).
   */
  keyboardEntryId: string | null;
  isCollapsed: boolean;
  linkComponent: NavLinkComponent;
  activeVariant?: AppSidebarProps["activeVariant"];
  autoCloseMobileOnNavigate: boolean;
  isMobileOpen: boolean;
  // v0.3.0 (C2, L54): accepts reason for the discriminator. Click handler
  // passes "item-click"; parent forwards to finalHandle.closeMobile(reason).
  onCloseMobile: (reason: AppSidebarMobileOpenReason) => void;

  // Section state — driven by reducer in parent
  collapsedSectionIds: ReadonlySet<string>;
  onToggleSection: (sectionId: string) => void;

  // Consumer event hooks
  onItemClick?: (args: AppSidebarEventArgs["itemClick"]) => void;
  onItemHover?: (args: AppSidebarEventArgs["itemHover"]) => void;
  onItemFocus?: (args: AppSidebarEventArgs["itemFocus"]) => void;
  onItemNavigate?: (args: AppSidebarEventArgs["itemNavigate"]) => void;
  onSectionToggle?: (args: AppSidebarEventArgs["sectionToggle"]) => void;

  // Slot priority
  renderItem?: AppSidebarProps["renderItem"];
  renderSection?: AppSidebarProps["renderSection"];
  renderBadge?: AppSidebarProps["renderBadge"];
  renderTooltipContent?: AppSidebarProps["renderTooltipContent"];

  // v0.2.0 — href resolution (L42 + L43)
  hrefTemplateValues?: AppSidebarProps["hrefTemplateValues"];
  resolveHref?: AppSidebarProps["resolveHref"];
}

/**
 * Renders the NavEntry[] list — flat NavItems, NavSections, and NavSeparators.
 *
 * C3 surface: flat items + separators. Sections render their items in a
 * single ungrouped list (full section UI with title + collapsible header
 * lands C4 in parts/sidebar-nav-section.tsx).
 *
 * Click sequence per L28:
 *   1. consumer's item.onClick fires sync
 *   2. onItemClick (component-level) fires sync
 *   3. if event.defaultPrevented → stop
 *   4. queueMicrotask → onItemNavigate + autoCloseMobileOnNavigate
 *
 * Disabled items short-circuit at step 1 (L27).
 */
export function SidebarNavList({
  entries,
  activeItemId,
  focusedItemId,
  keyboardEntryId,
  isCollapsed,
  linkComponent,
  activeVariant,
  autoCloseMobileOnNavigate,
  isMobileOpen,
  onCloseMobile,
  collapsedSectionIds,
  onToggleSection,
  onItemClick,
  onItemHover,
  onItemFocus,
  onItemNavigate,
  onSectionToggle,
  renderItem,
  renderSection,
  renderBadge,
  renderTooltipContent,
  hrefTemplateValues,
  resolveHref,
}: SidebarNavListProps) {
  // Roving tabindex (L37). The "entry point" rule:
  //   - Some row has the user's focus      → only that row is tabbable.
  //   - Nothing focused yet                 → the keyboard entry row is tabbable.
  //   - Disabled items always pass to -1.
  const resolveRovingTabIndex = (itemId: string): 0 | -1 => {
    if (focusedItemId) return focusedItemId === itemId ? 0 : -1;
    return keyboardEntryId === itemId ? 0 : -1;
  };
  const handleItemClick =
    (item: NavItem, sectionId: string | null, indexInSection: number) =>
    (event: React.MouseEvent) => {
      // L27 — disabled items short-circuit at step 1
      if (item.disabled) {
        event.preventDefault();
        return;
      }
      // Step 1 — consumer's per-item onClick
      item.onClick?.(event);
      // Step 2 — component-level onItemClick
      onItemClick?.({ item, isActive: activeItemId === item.id, event });
      // Step 3 — short-circuit if cancelled
      if (event.defaultPrevented) return;
      // Step 4 — microtask defer the navigation-side effects
      queueMicrotask(() => {
        onItemNavigate?.({ item });
        if (autoCloseMobileOnNavigate && isMobileOpen) {
          onCloseMobile("item-click");
        }
      });
      // Intentionally allow native <a> navigation to proceed unless
      // consumer called preventDefault in step 1 or 2.
      void sectionId;
      void indexInSection;
    };

  // v0.3.0 (C1, L55): renderRow always wraps in a SINGLE `<li>`. SidebarNavRow
  // returns only the tooltip-wrapped link (no internal `<li>`). The renderItem
  // slot path uses the SAME `<li>` wrapper — so consumer's
  // `renderItem={({ defaultRender }) => defaultRender}` produces
  // `<li><a>…</a></li>` instead of the v0.2.x `<li><li>…</li></li>` bug.
  // Item-level `className` + `data-testid` are applied to this wrapper.
  /*
   * v0.3.1 — hover/focus emitters. Disabled rows short-circuit exactly as they
   * do for clicks (L27): a row the user cannot activate should not report
   * interest in it either, or a consumer using these for prefetch would warm
   * routes the user can never reach.
   */
  const handleItemHover =
    (item: NavItem) => (event: React.MouseEvent) => {
      if (item.disabled) return;
      onItemHover?.({ item, event });
    };
  const handleItemFocus =
    (item: NavItem) => (event: React.FocusEvent) => {
      if (item.disabled) return;
      onItemFocus?.({ item, event });
    };

  const renderRow = (item: NavItem, sectionId: string | null, indexInSection: number) => {
    const isActive = activeItemId === item.id;
    const isFocused = focusedItemId === item.id;
    const rovingTabIndex = resolveRovingTabIndex(item.id);
    const defaultRender = (
      <SidebarNavRow
        item={item}
        isActive={isActive}
        isCollapsed={isCollapsed}
        isFocused={isFocused}
        rovingTabIndex={rovingTabIndex}
        linkComponent={linkComponent}
        activeVariant={activeVariant}
        onClick={handleItemClick(item, sectionId, indexInSection)}
        onMouseEnter={onItemHover ? handleItemHover(item) : undefined}
        onFocus={onItemFocus ? handleItemFocus(item) : undefined}
        renderBadge={renderBadge}
        renderTooltipContent={renderTooltipContent}
        hrefTemplateValues={hrefTemplateValues}
        resolveHref={resolveHref}
      />
    );
    const body = renderItem
      ? renderItem({
          item,
          isActive,
          isCollapsed,
          isFocused,
          isDisabled: item.disabled ?? false,
          sectionId,
          indexInSection,
          defaultRender,
        })
      : defaultRender;
    return (
      <li
        key={item.id}
        className={cn("list-none", item.className)}
        data-testid={item["data-testid"]}
      >
        {body}
      </li>
    );
  };

  return (
    <ul
      role="list"
      className={cn(
        "flex flex-1 flex-col gap-1 overflow-y-auto",
        // C5 hooks: motion-safe transitions will live here
      )}
    >
      {entries.map((entry, i) => {
        if (entry.kind === "separator") {
          return <SidebarNavSeparator key={entry.id ?? `sep-${i}`} />;
        }
        if (entry.kind === "section") {
          const isSectionCollapsed = collapsedSectionIds.has(entry.id);
          const isSectionFocused = focusedItemId === entry.id;
          const sectionRovingTabIndex =
            entry.collapsible ? resolveRovingTabIndex(entry.id) : -1;
          const handleSectionToggle = () => {
            onToggleSection(entry.id);
            onSectionToggle?.({ section: entry, collapsed: !isSectionCollapsed });
          };
          const defaultSection = (
            <SidebarNavSection
              key={entry.id}
              section={entry}
              isCollapsed={isSectionCollapsed}
              isSidebarCollapsed={isCollapsed}
              visibleItemCount={entry.items.length}
              isFocused={isSectionFocused}
              rovingTabIndex={sectionRovingTabIndex}
              onToggle={handleSectionToggle}
            >
              {entry.items.map((child, idx) => renderRow(child, entry.id, idx))}
            </SidebarNavSection>
          );
          if (!renderSection) return defaultSection;
          // `renderSection` is expected to return an `<li>` (typically by
          // forwarding `defaultRender` or composing its own list-item).
          // Fragment carries the key without injecting an invalid DOM node
          // between the `<ul>` parent and the consumer's `<li>`.
          return (
            <Fragment key={entry.id}>
              {renderSection({
                section: entry,
                isCollapsed: isSectionCollapsed,
                visibleItemCount: entry.items.length,
                defaultRender: defaultSection,
              })}
            </Fragment>
          );
        }
        // Top-level NavItem — renderRow returns an `<li>` directly with
        // the key already applied, so no wrapper element is needed.
        return renderRow(entry, null, i);
      })}
    </ul>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { getActiveVariantClasses } from "../lib/active-variant-classes";
import { resolveItemHref } from "../lib/href-resolver";
import type {
  NavBadgeConfig,
  NavItem,
  NavLinkComponent,
  AppSidebarProps,
} from "../types";
import { Icon } from "./icon";
import { NavBadge } from "./nav-badge";
import { TooltipWrapper } from "./tooltip-wrapper";

interface SidebarNavRowProps {
  item: NavItem;
  isActive: boolean;
  isCollapsed: boolean;
  isFocused: boolean;
  /**
   * Roving tabindex (L37). `0` when this row is the keyboard entry point
   * (= focused row OR — when nothing is focused — the first focusable row);
   * `-1` otherwise. Disabled items always pass through to `tabIndex={-1}`.
   */
  rovingTabIndex: 0 | -1;
  linkComponent: NavLinkComponent;
  activeVariant?: AppSidebarProps["activeVariant"];
  onClick: (event: React.MouseEvent) => void;
  // v0.3.1 — `NavLinkProps` declared `onMouseEnter`/`onFocus` from the start;
  // nothing ever passed them, so `onItemHover`/`onItemFocus` were inert props
  // on the public surface for the component's whole life.
  onMouseEnter?: (event: React.MouseEvent) => void;
  onFocus?: (event: React.FocusEvent) => void;
  renderBadge?: AppSidebarProps["renderBadge"];
  renderTooltipContent?: AppSidebarProps["renderTooltipContent"];
  // v0.2.0 — href resolution (L42 + L43)
  hrefTemplateValues?: AppSidebarProps["hrefTemplateValues"];
  resolveHref?: AppSidebarProps["resolveHref"];
}

/**
 * Resolve a NavItem's badge config (shorthand number/string → full config).
 */
function resolveBadgeConfig(
  badge: NavItem["badge"],
): NavBadgeConfig | null {
  if (badge === undefined || badge === null) return null;
  if (typeof badge === "number" || typeof badge === "string") {
    return { value: badge };
  }
  // Already a NavBadgeConfig (or arbitrary ReactNode — treat as value)
  if (typeof badge === "object" && "value" in badge) {
    return badge as NavBadgeConfig;
  }
  // Bare ReactNode badge
  return { value: badge as NavBadgeConfig["value"] };
}

export function SidebarNavRow({
  item,
  isActive,
  isCollapsed,
  isFocused,
  rovingTabIndex,
  linkComponent: LinkComponent,
  activeVariant,
  onClick,
  onMouseEnter,
  onFocus,
  renderBadge,
  renderTooltipContent,
  hrefTemplateValues,
  resolveHref,
}: SidebarNavRowProps) {
  const isDisabled = item.disabled ?? false;
  // v0.2.0: resolveItemHref applies the precedence pipeline (callback wins
  // over template-value substitution; fallback to item.href as-is). When
  // neither v0.2 prop is provided, this is byte-identical to v0.1 behavior.
  const resolvedHref = resolveItemHref(item, { templateValues: hrefTemplateValues, resolveHref });
  const href = resolvedHref ?? "#";

  const badgeConfig = resolveBadgeConfig(item.badge);
  const defaultBadge = badgeConfig ? (
    <NavBadge {...badgeConfig} />
  ) : null;
  const badgeNode = renderBadge && badgeConfig
    ? renderBadge({
        item,
        badge: badgeConfig,
        position: isCollapsed ? "corner" : "inline-end",
        defaultRender: defaultBadge,
      })
    : defaultBadge;

  // Tooltip content when collapsed — label + optional shortcut + optional description
  const tooltipContent = renderTooltipContent
    ? renderTooltipContent({ item, isActive })
    : (item.tooltipContent ?? (
        <div className="flex flex-col gap-0.5">
          <span className="font-medium">{item.label}</span>
          {item.shortcut && (
            <span className="text-[10px] text-muted-foreground">
              {item.shortcut}
            </span>
          )}
          {!isActive && item.description && (
            <span className="text-[10px] text-muted-foreground/90">
              {item.description}
            </span>
          )}
        </div>
      ));

  const linkEl = (
    <LinkComponent
      href={href}
      onClick={onClick}
      onMouseEnter={onMouseEnter}
      onFocus={onFocus}
      aria-current={isActive ? "page" : undefined}
      aria-label={isCollapsed ? item.label : undefined}
      aria-disabled={isDisabled || undefined}
      data-active={isActive}
      data-focused={isFocused || undefined}
      data-nav-id={item.id}
      tabIndex={isDisabled ? -1 : rovingTabIndex}
      target={item.target}
      rel={item.rel}
      className={cn(
        "group relative flex items-center gap-3 rounded-lg px-3 py-2.5",
        "text-sm font-medium",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card",
        // Active vs inactive paint via L12 variant matrix
        getActiveVariantClasses(activeVariant, isActive),
        // Disabled (L27)
        isDisabled && "pointer-events-none cursor-not-allowed opacity-50",
        // Center icon when collapsed
        isCollapsed && "justify-center",
      )}
    >
      {(item.icon !== undefined && item.icon !== null) || isCollapsed ? (
        <span className="relative inline-flex h-5 w-5 shrink-0 items-center justify-center">
          {item.icon !== undefined && item.icon !== null ? (
            <Icon icon={item.icon} />
          ) : (
            // Fallback glyph when collapsed AND no explicit icon —
            // first letter of the label, styled like an icon. Keeps the
            // row visually anchored so the corner-badge has something to
            // sit on top of.
            <span
              aria-hidden="true"
              className="inline-flex h-5 w-5 items-center justify-center rounded-sm bg-muted text-[10px] font-semibold uppercase text-muted-foreground"
            >
              {item.label?.[0] ?? "•"}
            </span>
          )}
          {/* Badge in corner position when collapsed */}
          {isCollapsed && badgeNode}
        </span>
      ) : null}
      {!isCollapsed && (
        <span className="flex-1 truncate">{item.label}</span>
      )}
      {!isCollapsed && item.shortcut && (
        <span
          className={cn(
            "rounded px-1.5 py-0.5 font-mono text-xs",
            isActive ? "bg-primary-foreground/10" : "bg-muted text-muted-foreground",
          )}
        >
          {item.shortcut}
        </span>
      )}
      {!isCollapsed && item.accessory && (
        <span className="inline-flex items-center">{item.accessory}</span>
      )}
      {/* Badge in inline-end position when expanded */}
      {!isCollapsed && badgeNode}
    </LinkComponent>
  );

  // v0.3.0 (C1, L55): SidebarNavRow returns ONLY the tooltip-wrapped link.
  // The outer `<li>` is owned by SidebarNavList — consistent across the
  // default path and the renderItem-slot path, so consumer's
  // `renderItem={({ defaultRender }) => defaultRender}` no longer produces
  // double-nested `<li><li>...</li></li>`.
  return (
    <TooltipWrapper
      content={tooltipContent}
      side="right"
      disabled={!isCollapsed}
    >
      {linkEl}
    </TooltipWrapper>
  );
}

"use client";

import { ChevronDown } from "lucide-react";
import { useId } from "react";
import { cn } from "@/lib/utils";
import type { NavSection } from "../types";
import { Icon } from "./icon";

interface SidebarNavSectionProps {
  section: NavSection;
  isCollapsed: boolean; // section's own collapse state (NOT sidebar's)
  isSidebarCollapsed: boolean; // sidebar collapsed = icon-only mode
  visibleItemCount: number;
  isFocused: boolean;
  /** Roving tabindex for the collapsible header button (L37). */
  rovingTabIndex: 0 | -1;
  children: React.ReactNode; // the section's items (already rendered by parent)
  onToggle: () => void;
}

/**
 * Section header + collapsible body wrapper.
 *
 * Behavior:
 *  - collapsible=true → header is a <button aria-expanded aria-controls> that toggles
 *  - collapsible=false → header is a <h6 role="heading"> (label only, not focusable)
 *
 * At sidebar-collapsed mode (icon-only), section title hides; only the icon
 * shows. If section has no icon, the section header collapses to a thin
 * separator-like divider so groups remain visually distinct.
 */
export function SidebarNavSection({
  section,
  isCollapsed,
  isSidebarCollapsed,
  visibleItemCount,
  isFocused,
  rovingTabIndex,
  children,
  onToggle,
}: SidebarNavSectionProps) {
  const bodyId = useId();
  const collapsible = section.collapsible ?? false;

  // Sidebar at icon-only mode: render condensed
  if (isSidebarCollapsed) {
    return (
      <li className="list-none">
        {section.icon || section.title ? (
          <div className="px-3 py-1.5" role="presentation" aria-hidden="true">
            {section.icon ? (
              <Icon
                icon={section.icon}
                className="h-3.5 w-3.5 text-muted-foreground"
              />
            ) : (
              <div className="h-px w-full bg-border" />
            )}
          </div>
        ) : (
          <div className="my-1 h-px w-full bg-border" role="presentation" />
        )}
        {!isCollapsed && (
          // <ul> (not <div>) so the `<li>` rows produced by SidebarNavRow
          // are valid direct children. Outer wrapper is also <li> (section
          // root), so the structure is <li><ul><li>...</li></ul></li> —
          // valid HTML for a nested list group.
          <ul
            id={bodyId}
            role="group"
            aria-label={section.title}
            className="flex flex-col gap-1"
          >
            {children}
          </ul>
        )}
      </li>
    );
  }

  // Expanded sidebar — full section UI
  const headerInner = (
    <span className="flex flex-1 items-center gap-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
      {section.icon && <Icon icon={section.icon} className="h-3.5 w-3.5" />}
      <span className="truncate">{section.title}</span>
      {visibleItemCount > 0 && (
        <span
          className="ml-1 text-[10px] font-normal text-muted-foreground/70"
          aria-hidden="true"
        >
          {visibleItemCount}
        </span>
      )}
    </span>
  );

  return (
    <li className="list-none">
      {collapsible ? (
        <button
          type="button"
          onClick={onToggle}
          aria-expanded={!isCollapsed}
          aria-controls={bodyId}
          data-nav-id={section.id}
          data-focused={isFocused || undefined}
          tabIndex={rovingTabIndex}
          className={cn(
            "flex w-full items-center gap-2 rounded-md px-3 py-1.5 text-left",
            "hover:bg-muted/50",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card",
          )}
        >
          {headerInner}
          <ChevronDown
            className={cn(
              "h-3.5 w-3.5 text-muted-foreground",
              "motion-safe:transition-transform motion-safe:duration-200",
              isCollapsed && "-rotate-90",
              // RTL: chevron rotates the OTHER way when collapsed so it
              // still points "outward" from the open direction
              isCollapsed && "rtl:rotate-90",
            )}
            aria-hidden="true"
          />
        </button>
      ) : section.title ? (
        // Non-collapsible header — pure label, not focusable
        <h6 className="px-3 py-1.5">{headerInner}</h6>
      ) : null}

      {!isCollapsed && (
        <ul
          id={bodyId}
          role="group"
          aria-label={section.title}
          className="mt-0.5 flex flex-col gap-1"
        >
          {children}
        </ul>
      )}
    </li>
  );
}

import { cn } from "@/lib/utils";

interface SidebarNavSeparatorProps {
  className?: string;
}

/**
 * Thin horizontal divider between nav groups.
 * Spec'd as separate part so the visual can be themed via consumer CSS.
 */
export function SidebarNavSeparator({ className }: SidebarNavSeparatorProps) {
  return (
    <li role="presentation" className={cn("my-2 px-3", className)}>
      <div className="h-px w-full bg-border" />
    </li>
  );
}

"use client";

import { cloneElement, isValidElement } from "react";
import { PanelLeft } from "lucide-react";
import { cn } from "@/lib/utils";
import { useAppSidebarContextOrNull } from "../contexts/sidebar-nav-context";
import type { AppSidebarHandle, AppSidebarTriggerProps } from "../types";

type SlotCloneProps = React.HTMLAttributes<HTMLElement> & {
  type?: "button";
  children?: React.ReactNode;
};

/**
 * Minimal local slot (v0.3.1 — replaces the former `radix-ui` Slot import,
 * which was undeclared in meta/registry.json AND forbidden by the validator;
 * it broke module resolution on Base-UI consumers). Clones the single child
 * element and merges the trigger props onto it: `className` joined, `style`
 * merged (child wins), event handlers composed (child first, then trigger),
 * any other overlapping prop child-wins. The child's own `ref` is preserved
 * by `cloneElement` — no ref is ever passed in `triggerProps`.
 */
function SlotClone({ children, ...slotProps }: SlotCloneProps) {
  if (!isValidElement(children)) {
    if (process.env.NODE_ENV !== "production") {
      console.warn(
        "[app-sidebar] <AppSidebarTrigger asChild> expects a single React element child — got none. Rendering nothing.",
      );
    }
    return null;
  }
  const childProps = children.props as Record<string, unknown>;
  const merged: Record<string, unknown> = { ...slotProps };
  for (const key of Object.keys(slotProps)) {
    const slotValue = (slotProps as Record<string, unknown>)[key];
    const childValue = childProps[key];
    if (childValue === undefined) continue;
    if (/^on[A-Z]/.test(key) && typeof slotValue === "function" && typeof childValue === "function") {
      merged[key] = (...args: unknown[]) => {
        (childValue as (...a: unknown[]) => void)(...args);
        (slotValue as (...a: unknown[]) => void)(...args);
      };
    } else if (key === "className") {
      merged[key] = cn(slotValue as string | undefined, childValue as string | undefined);
    } else if (key === "style") {
      merged[key] = {
        ...(slotValue as React.CSSProperties),
        ...(childValue as React.CSSProperties),
      };
    } else {
      merged[key] = childValue;
    }
  }
  return cloneElement(children, merged);
}

/**
 * Companion trigger — mount in your app header to open the mobile drawer.
 *
 * Resolution order (L17 + L40):
 *   1. Explicit `controls` ref/handle (escape hatch) — wins
 *   2. Nearest AppSidebarContext (works when trigger is a DESCENDANT
 *      of <AppSidebar>; siblings can't read it because the context
 *      provider sits inside the sidebar's own render tree)
 *   3. Neither → dev-only console.warn + no-op
 *
 * Resolution happens at CLICK TIME, not render time, because the ref's
 * `.current` populates after the sidebar's `useImperativeHandle` runs
 * (post-mount). Resolving at render time would see `null` on first paint.
 *
 * Visual: hamburger icon (PanelLeft) — opens the drawer. Closing is
 * handled by the drawer's own SheetContent close-X (shipped by shadcn's
 * Sheet primitive) + Esc + outside-click. The trigger button itself
 * does NOT flip its icon based on drawer state — keeps the component
 * stateless and avoids the cross-tree re-render problem for v0.1.
 * A future AppSidebarProvider wrapper will enable trigger state
 * reflection across React subtrees if needed.
 *
 * Override the icon entirely via `children` (custom node) or `asChild`
 * (compose onto consumer's own element via the local SlotClone above).
 */
export function AppSidebarTrigger({
  controls,
  className,
  children,
  "aria-label": ariaLabel,
  asChild = false,
}: AppSidebarTriggerProps) {
  const ctx = useAppSidebarContextOrNull();

  const handleClick = () => {
    // Resolve handle at click time (not render time) — ref.current may
    // still be null on first render before useImperativeHandle runs.
    let resolved: AppSidebarHandle | null = null;
    if (controls) {
      if (typeof controls === "object" && controls !== null && "current" in controls) {
        resolved = (controls as React.RefObject<AppSidebarHandle | null>).current;
      } else {
        resolved = controls as AppSidebarHandle;
      }
    }
    if (!resolved && ctx) {
      resolved = ctx.handle;
    }
    if (resolved) {
      // v0.3.0 (C2, L54 + Q25): companion trigger always identifies as
      // "trigger" so consumers wiring onMobileOpenChange to analytics can
      // distinguish hamburger taps from other close paths.
      resolved.toggleMobile("trigger");
    } else if (process.env.NODE_ENV !== "production") {
      console.warn(
        "[app-sidebar] <AppSidebarTrigger> clicked with no <AppSidebar> in context and no `controls` prop — no-op.",
      );
    }
  };

  const sidebarId = ctx?.sidebarId;

  const triggerProps = {
    type: "button" as const,
    onClick: handleClick,
    "aria-controls": sidebarId,
    "aria-haspopup": "dialog" as const,
    "aria-label": ariaLabel ?? "Open navigation",
    className: cn(
      !asChild &&
        "inline-flex h-9 w-9 items-center justify-center rounded-md text-foreground hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
      className,
    ),
  };

  if (asChild) {
    return <SlotClone {...triggerProps}>{children}</SlotClone>;
  }

  return (
    <button {...triggerProps}>
      {children ?? <PanelLeft className="h-4 w-4" aria-hidden="true" />}
    </button>
  );
}

"use client";

import { cn } from "@/lib/utils";
import type { AppSidebarEventArgs } from "../types";

interface SidebarSkipLinkProps {
  target: string;
  label: string;
  onActivated?: (args: AppSidebarEventArgs["skipLinkActivated"]) => void;
}

/**
 * Opt-in skip link (L31). Hidden until focused; appears at the top of the
 * sidebar's stacking context on keyboard focus. Activating jumps focus /
 * scroll to the consumer-supplied `skipLinkTarget` (e.g. `#main-content`).
 *
 * The component intentionally renders a plain `<a>` — using the consumer's
 * `linkComponent` for an in-page anchor would risk SPA frameworks treating
 * it as a route change. Native anchor behavior is the right primitive.
 */
export function SidebarSkipLink({
  target,
  label,
  onActivated,
}: SidebarSkipLinkProps) {
  return (
    <a
      href={target}
      data-sidebar-skip-link
      onClick={(event) => onActivated?.({ event })}
      className={cn(
        // sr-only by default — appears on focus
        "sr-only focus:not-sr-only",
        "focus:absolute focus:left-2 focus:top-2 focus:z-50",
        // RTL: skip link should sit on the same logical inline-start edge,
        // which means physical-right when direction is RTL
        "rtl:focus:left-auto rtl:focus:right-2",
        "focus:inline-flex focus:items-center focus:rounded-md",
        "focus:bg-card focus:px-3 focus:py-2",
        "focus:text-sm focus:font-medium focus:text-foreground",
        "focus:shadow-md focus:ring-1 focus:ring-border",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card",
      )}
    >
      {label}
    </a>
  );
}

"use client";

import {
  cloneElement,
  isValidElement,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from "react";
import { cn } from "@/lib/utils";

interface TooltipWrapperProps {
  content: ReactNode;
  children: ReactNode;
  side?: "right" | "top" | "bottom" | "left";
  disabled?: boolean;
  /** Hover show-delay in ms (keyboard focus shows immediately). Default 300. */
  delay?: number;
}

/** Gap between the wrapped element and the bubble (old Radix sideOffset parity). */
const SIDE_OFFSET_PX = 8;

type TooltipSide = NonNullable<TooltipWrapperProps["side"]>;

interface TooltipPosition {
  top: number;
  left: number;
}

function computePosition(rect: DOMRect, side: TooltipSide): TooltipPosition {
  switch (side) {
    case "left":
      return { top: rect.top + rect.height / 2, left: rect.left - SIDE_OFFSET_PX };
    case "top":
      return { top: rect.top - SIDE_OFFSET_PX, left: rect.left + rect.width / 2 };
    case "bottom":
      return { top: rect.bottom + SIDE_OFFSET_PX, left: rect.left + rect.width / 2 };
    case "right":
      return { top: rect.top + rect.height / 2, left: rect.right + SIDE_OFFSET_PX };
  }
}

const SIDE_TRANSFORM: Record<TooltipSide, string> = {
  right: "translateY(-50%)",
  left: "translate(-100%, -50%)",
  top: "translate(-50%, -100%)",
  bottom: "translateX(-50%)",
};

/**
 * Tooltip wrapper for collapsed-sidebar row labels.
 *
 * v0.3.2 (F-cross-13 path-b): the shadcn Tooltip primitive is GONE from this
 * wrapper. `children` is an arbitrary interactive element (nav link,
 * primary-action button) and BOTH backends render `TooltipTrigger` as a
 * native `<button>` — composing required `asChild` (Base UI rejects it) and
 * wrapping without it nests interactive elements inside a button. So this is
 * now a tiny local tooltip: a `position: fixed` bubble (escapes the nav
 * list's overflow clipping the same way the old Radix portal did), shown
 * after `delay` ms on hover / immediately on keyboard (:focus-visible)
 * focus, hidden on leave / blur / press / Escape / any scroll.
 * `aria-describedby` is cloned onto the child element. `delay` is honored
 * cross-backend via setTimeout — no Radix-only `delayDuration` anywhere.
 * Trade-offs vs Radix: no arrow, no collision flipping, no cross-tooltip
 * skip-delay grouping.
 *
 * When `disabled` is true (e.g., expanded sidebar mode), children render
 * without any wrapper element at all.
 */
export function TooltipWrapper({
  content,
  children,
  side = "right",
  disabled,
  delay = 300,
}: TooltipWrapperProps) {
  const tooltipId = useId();
  const wrapperRef = useRef<HTMLSpanElement | null>(null);
  const showTimerRef = useRef<number | null>(null);
  const [position, setPosition] = useState<TooltipPosition | null>(null);

  const clearShowTimer = useCallback(() => {
    if (showTimerRef.current !== null) {
      window.clearTimeout(showTimerRef.current);
      showTimerRef.current = null;
    }
  }, []);

  const show = useCallback(() => {
    const el = wrapperRef.current;
    if (!el) return;
    // Parity with the old asChild path: a pointer-events-none child (disabled
    // nav row) never received hover, so its tooltip never opened.
    const child = el.firstElementChild;
    if (
      child instanceof HTMLElement &&
      getComputedStyle(child).pointerEvents === "none"
    ) {
      return;
    }
    setPosition(computePosition(el.getBoundingClientRect(), side));
  }, [side]);

  const hide = useCallback(() => {
    clearShowTimer();
    setPosition(null);
  }, [clearShowTimer]);

  // Fixed-position coords go stale the moment anything scrolls (Radix
  // repositioned via floating middleware; we simply dismiss). Capture phase
  // so the nav list's own scroll container is caught too.
  useEffect(() => {
    if (position === null) return;
    const onScroll = () => setPosition(null);
    window.addEventListener("scroll", onScroll, true);
    window.addEventListener("resize", onScroll);
    return () => {
      window.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("resize", onScroll);
    };
  }, [position]);

  // Unmount — drop any pending show timer.
  useEffect(() => clearShowTimer, [clearShowTimer]);

  // `disabled` flipping true while shown (e.g. the rail expands under a
  // resting pointer) skips render below but keeps state — the stale bubble
  // would resurrect at old coords on the next collapse. Render-phase
  // adjustment (react.dev "adjusting state when a prop changes"); a pending
  // show-timer self-guards via the nulled wrapperRef, so only committed
  // position needs the reset.
  const [prevDisabled, setPrevDisabled] = useState(disabled);
  if (disabled !== prevDisabled) {
    setPrevDisabled(disabled);
    if (disabled) setPosition(null);
  }

  if (disabled) return <>{children}</>;

  // Wire aria-describedby onto the wrapped element itself (the focusable
  // thing), composing with any describedby it already carries. Non-element
  // children (arbitrary renderItem output) render unwired — best-effort.
  let describedChildren = children;
  if (isValidElement(children)) {
    const element = children as ReactElement<{ "aria-describedby"?: string }>;
    const existing = element.props["aria-describedby"];
    describedChildren = cloneElement(element, {
      "aria-describedby": existing ? `${existing} ${tooltipId}` : tooltipId,
    });
  }

  return (
    <span
      ref={wrapperRef}
      data-slot="app-sidebar-tooltip-wrapper"
      className="relative block"
      onMouseEnter={() => {
        clearShowTimer();
        if (delay <= 0) {
          show();
          return;
        }
        showTimerRef.current = window.setTimeout(show, delay);
      }}
      onMouseLeave={hide}
      onFocus={(event) => {
        // Radix parity: keyboard focus opens instantly; mouse-press focus doesn't.
        const target = event.target as HTMLElement;
        if (typeof target.matches === "function" && target.matches(":focus-visible")) {
          show();
        }
      }}
      onBlur={hide}
      onPointerDown={hide}
      onKeyDown={(event) => {
        if (event.key === "Escape") hide();
      }}
    >
      {describedChildren}
      <span
        role="tooltip"
        id={tooltipId}
        data-side={side}
        style={
          position
            ? { top: position.top, left: position.left, transform: SIDE_TRANSFORM[side] }
            : undefined
        }
        className={cn(
          "pointer-events-none fixed z-50 w-fit max-w-xs items-center gap-1.5 rounded-md bg-foreground px-3 py-1.5 text-xs text-background",
          position ? "inline-flex" : "hidden",
        )}
      >
        {content}
      </span>
    </span>
  );
}
